CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type ENUM('page','article','review','country','faq') NOT NULL DEFAULT 'page',title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,excerpt TEXT NULL,body LONGTEXT NULL,image VARCHAR(500) NULL,author VARCHAR(120) NULL,status ENUM('draft','published') NOT NULL DEFAULT 'published',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY type_status_sort(type,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(40) NOT NULL,title VARCHAR(220) NOT NULL,eyebrow VARCHAR(220) NULL,body LONGTEXT NULL,image VARCHAR(500) NULL,button_label VARCHAR(120) NULL,button_url VARCHAR(500) NULL,theme ENUM('default','soft','dark') NOT NULL DEFAULT 'default',item_limit TINYINT UNSIGNED NOT NULL DEFAULT 6,sort_order INT NOT NULL DEFAULT 0,enabled TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY enabled_order(enabled,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
