INSERT IGNORE INTO content(type,title,slug,excerpt,body,status,sort_order) VALUES('page','How LipaHub Works','how-it-works','A simple overview of getting started.','<h2>Explore the platform</h2><p>Browse activities and learning resources, review requirements and follow each opportunity instructions.</p><h2>Create your account</h2><p>Use the registration link and follow the onboarding steps.</p>','published',1),('page','About LipaHub','about','Learn about the platform.','<p>LipaHub brings online activities, learning resources and community information together.</p>','published',2),('page','Frequently Asked Questions','faq','Answers to common questions.','<h2>Are earnings guaranteed?</h2><p>No. Activities, eligibility and outcomes vary. Review terms before participating.</p>','published',3),('article','LipaHub – Complete Guide','lipahub-complete-guide','An introduction to LipaHub and getting started.','<p>This guide introduces LipaHub and explains how to explore the platform.</p>','published',1),('country','LipaHub Kenya','lipahub-kenya','A guide to LipaHub in Kenya.','<p>Explore the platform and available activities in Kenya. Availability can change.</p>','published',1),('country','LipaHub Nigeria','lipahub-nigeria','A guide to LipaHub in Nigeria.','<p>Explore the platform and available activities in Nigeria. Availability can change.</p>','published',2),('country','LipaHub Ghana','lipahub-ghana','A guide to LipaHub in Ghana.','<p>Explore the platform and available activities in Ghana. Availability can change.</p>','published',3);
